/**
 * Classify one `term.onData` payload as real user input or as a mouse
 * report the terminal generated by itself.
 * ----------------------------------------------------------------------
 * WHY THIS EXISTS (the "moving the mouse jumps to the bottom" bug):
 *
 * xterm delivers mouse reports through `onData`, the same channel as
 * keystrokes. From `CoreMouseService.triggerMouseEvent`:
 *
 *     this._coreService.triggerDataEvent(encoded, true)
 *                                                 ^^^^ userInput = true
 *
 * so a mouse report is indistinguishable from typing at that boundary.
 * That is fine for the wire - the bytes must reach the application
 * either way - but it is wrong for INTENT. terminal.js's `onData`
 * handler treats every payload as "the user asked to be back at the
 * live bottom" and calls `TerminalScroll.pinToBottom()`, and it also
 * arms `AltScreenScroll.noteUserInput()`, the 1200ms typing quiet
 * period.
 *
 * Claude's fullscreen TUI enables `?1003h` (ANY-EVENT tracking), which
 * asks the terminal to report every pointer MOTION, not just drags. So
 * with no click and no selection, simply moving the mouse across the
 * terminal produced a stream of reports, each one re-pinning a user who
 * had deliberately scrolled up. Measured against the real vendored
 * xterm bundle: viewportY 347 (baseY 377) before three plain moves,
 * viewportY 377 after - one `pinToBottom` per motion event.
 *
 * This is the FOURTH owner of that decision to be removed. The first
 * three were xterm's own `scrollOnUserInput`, its selection drag-scroll
 * interval, and two `scrollIntoView({block:'end'})` listeners. The
 * principle is the one written up in terminal-scroll.js: only an
 * explicit request goes back to the bottom.
 *
 * The payloads are recognised by shape rather than by asking xterm,
 * because xterm exposes no per-event provenance on `onData`. Only two
 * shapes can arrive:
 *
 *   SGR / SGR_PIXELS  ESC [ < Cb ; Cx ; Cy (M|m)   <- what ?1006h selects
 *   X10 "DEFAULT"     ESC [ M  Cb Cx Cy           <- 3 raw bytes
 *
 * xterm routes the X10 form to `triggerBinaryEvent` (onBinary) rather
 * than onData, so in practice only the SGR form reaches this file; the
 * X10 pattern is matched anyway so a future encoding change cannot
 * quietly reintroduce the bug. Both are anchored whole-string: a mouse
 * report is always fired as its own data event, never spliced into a
 * chunk of typing, so a partial match would mean something else and
 * must be treated as user input.
 *
 * Fail-open is deliberate everywhere here: anything not positively
 * recognised as a mouse report is user input. Misclassifying typing as
 * a mouse report would break "typing takes me back to live", which is
 * the behaviour the pin exists to provide.
 */
(function () {
    'use strict';

    /**
     * SGR and SGR-pixel mouse reports: `ESC [ < Cb ; Cx ; Cy M` for a
     * press/motion and `... m` for a release. Coordinates are decimal
     * and unbounded in principle; the length caps keep the regex linear
     * and reject anything that is not plausibly a report.
     *
     * @type {RegExp}
     */
    var SGR_MOUSE_REPORT = /^\x1b\[<\d{1,5};\d{1,5};\d{1,5}[Mm]$/;

    /**
     * The legacy X10/VT200 form: `ESC [ M` followed by exactly three
     * single-byte fields (button, column, row), each offset by 32.
     *
     * @type {RegExp}
     */
    var X10_MOUSE_REPORT = /^\x1b\[M[\s\S]{3}$/;

    /**
     * Is this `onData` payload a mouse report the terminal generated,
     * rather than something the user typed or pasted?
     *
     * Callers use it to decide INTENT only. The bytes must still be
     * forwarded to the session either way - the running application
     * asked for these reports and needs them to track the pointer.
     *
     * @param {string} data - one payload as delivered by `term.onData`.
     * @returns {boolean} true only for a recognised whole mouse report;
     *   false for typing, pastes, empty strings and non-strings.
     */
    function isMouseReport(data) {
        if (typeof data !== 'string') return false;
        // Shortest possible report is ESC [ M + 3 bytes.
        if (data.length < 6) return false;
        return SGR_MOUSE_REPORT.test(data) || X10_MOUSE_REPORT.test(data);
    }

    window.TerminalInputKind = {
        isMouseReport: isMouseReport
    };
})();
